#include <stdio.h>

int find_pair(const int a[], int n, int target, int *first, int *second) {
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (a[i] + a[j] == target) {
                *first = i;
                *second = j;
                return 1;
            }
        }
    }
    return 0;
}

int main() {
    int a[] = {10, 3, 8, 7, 1};
    int x, y;
    if (find_pair(a, 5, 15, &x, &y)) {
        printf("%d %d\n", x, y);
    } else {
        printf("none\n");
    }
    return 0;
}
